/** remocn.dev logo, inline in running text: R mark on the baseline + "emocn". */
function RemocnLogo({ color }: { color: string }) {
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        letterSpacing: "-0.025em",
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto", alignSelf: "baseline" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </span>
  );
}

interface LineCascadeProps {
  value?: string;
  caption?: string;
  accent?: string;
  /** Text color of the caption, the remocn mark and the rain; overrides the theme. */
  ink?: string;
  background?: string;
  /** Typeface for the caption. Load it yourself; Hanken Grotesk by default. */
  fontFamily?: string;
  /** Weight of the caption. */
  fontWeight?: number;
  /** Distance between falling lines, in px at 720p. */
  lineSpacing?: number;
  /** Replaces the remocn mark in the caption. */
  logo?: React.ReactNode;
  grain?: boolean;
  /** Size of the figure and caption, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);

