type Pt = [number, number];
type Glyph = { advance: number; strokes: Pt[][] };
type Seg = [number, number, number, number];

const STROKE = 0.165;
const R = STROKE / 2;
const DW = 0.64;
const TRACK = 0.1;
const CX = DW / 2;
const X0 = R;
const X1 = DW - R;
const Y0 = R;
const Y1 = 1 - R;

function arc(
  cx: number,
  cy: number,
  rx: number,
  ry: number,
  a0: number,
  a1: number,
  n = 40,
): Pt[] {
  const pts: Pt[] = [];
  for (let i = 0; i <= n; i++) {
    const a = ((a0 + ((a1 - a0) * i) / n) * Math.PI) / 180;
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a)]);
  }
  return pts;
}

const JUNCTION = 0.46;
const TOP_BOWL = { cy: (Y0 + JUNCTION) / 2, ry: (JUNCTION - Y0) / 2, rx: 0.2 };
const LOW_BOWL = {
  cy: (JUNCTION + Y1) / 2,
  ry: (Y1 - JUNCTION) / 2,
  rx: CX - R,
};
const BOWL = { cy: 0.655, ry: Y1 - 0.655, rx: CX - R };

const GLYPHS: Record<string, Glyph> = {
  "0": { advance: DW, strokes: [arc(CX, 0.5, CX - R, 0.5 - R, 0, 360, 64)] },
  "1": {
    advance: DW,
    strokes: [
      [
        [0.13, 0.25],
        [0.4, Y0],
        [0.4, Y1],
      ],
    ],
  },
  "2": {
    advance: DW,
    strokes: [
      [...arc(CX, 0.3, CX - R, 0.3 - R, 182, 395), [X0, Y1], [X1 + 0.01, Y1]],
    ],
  },
  "3": {
    advance: DW,
