const ELEMENT_PROP_KEYS = new Set(["theme","value","caption","fontWeight","lineSpacing","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "240",
  caption: "launch films rendered with remocn today",
  fontWeight: 400,
  lineSpacing: 6.5,
  accent: "#3B5BFD",
  fontFamily: "Hanken Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type LineCascadeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LineCascadeBase>;

const LineCascadeInner = forwardRef<
  HTMLDivElement,
  LineCascadeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LineCascade>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LineCascadeBase
          {...(componentProps as unknown as ComponentProps<typeof LineCascadeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LineCascade = Interactive.withSchema({
